function evaluate(node, env) {
  switch (node.kind) {
    case 'num': return node.value;
    case 'var': {
      if (!(node.name in env)) throw new Error(`모르는 이름: ${node.name}`);
      return env[node.name];
    }
    case 'bin': {
      const a = evaluate(node.left, env);
      const b = evaluate(node.right, env);
      switch (node.op) {
        case '+': return a + b;
        case '-': return a - b;
        case '*': return a * b;
        case '/':
          if (b === 0) throw new Error('0 으로 나눌 수 없다');
          return a / b;
      }
    }
    case 'if':  return evaluate(node.cond, env) ? evaluate(node.then, env) : evaluate(node.else, env);
  }
  throw new Error(`모르는 노드: ${node.kind}`);
}

evaluate(parse(tokenize('2 + 3 * age')), { age: 4 });   // 14

// 안쪽 범위는 바깥을 참조한다
function lookup(env, name) {
  for (let e = env; e; e = e.parent) if (name in e.vars) return e.vars[name];
  throw new Error(`모르는 이름: ${name}`);
}
